def cleanup_shared_memory_blocks(self):
    """Clean up orphaned shared memory blocks."""
    try:
        if os.path.exists("/dev/shm"):
            import glob
            patterns = ["/dev/shm/psm_*", "/dev/shm/wnsm_*"]
            cleaned_count = 0

            for pattern in patterns:
                blocks = glob.glob(pattern)
                for block in blocks:
